A convex function $f : \mathbb{R}^{n} \rightarrow \mathbb{R}$ is self-concordant if there
exists a constant $\kappa$ such that for every $x \in \mathbb{R}^{n}$ and every $h \in \mathbb{R}^{n}$, we have :
\begin{equation*}
    \left|\nabla^{3} f(x)[h, h, h]\right| \leq \kappa\left(\nabla^{2} f(x)[h, h]\right)^{3 / 2},
\end{equation*}
$f$ is standard self-concordant if the above is satisfied for $\kappa = 2$.

\label{selfconc}
(Lemma 4.1, ~\citet{gaogoldself})

For $F$ standard self-concordant, for all $0 \leq t<\frac{1}{\delta_k}$:
\begin{equation*}
\quad F(x_k+t d_k) \leq F(x_k)+t g(x_k)^{T} d_k-\delta_k t-\log (1-\delta_k t).
\end{equation*}

\label{dhdprob}
(Lemma 2 in ~\citep{Roosta-Khorasani2019}
Under Assumptions 1. and 2., given any $ 0<\varepsilon, p<1 \text { and } x, d \in \mathbb{R}^{n}$, if $|X| \geq 16 \kappa^{2} \ln (2 n / p) / \varepsilon^{2},$ we have:
\begin{equation}\label{eqn:conchess}
    \mathbb{P}\left(\left\| \nabla^{2} F_X(x)-\nabla^{2} F(\mathbf{x})\right\| \leq \varepsilon m\right) \geq 1-p,




\end{equation}
where $\|.\|$ is the operator norm induced by the Euclidean norm.

Let $0 <\nu\gamma, \varepsilon, p, \delta < 1$. Suppose that $F$ satisfies the Assumptions 1-4 and that we have an efficient way to compute $G(x)$ where \(\left\|\nabla F_{i}(\mathrm{x})\right\| \leq G(\mathrm{x}), \quad \forall i=1, \ldots, n\). Let $\{x_k, X_k, S_k\}$ be the set of iterates, and sample Hessian and gradient batches generated by taking the step $t_{k, \varepsilon}$ at iteration $k$ starting from any $x_0$, where $|S_{k}|, |X_{k}|$ are chosen such that Lemma \ref{gkprob} and Lemma \ref{dhdprob} are satisfied at each iteration. Then, for any $k$, with probability $(1-p)(1-\delta)$ we have :
	\begin{equation*}
	    (F(x_{k+1}) - F(x^*)) \leq \rho (F(x_k) - F(x^*)),
	\end{equation*}
     where $\rho=  1 - \frac{m(1-\nu)^2(1-\varepsilon)}{2(1+\nu^2) M (1+\frac{\gamma}{\sqrt{m}})}.$
	\label{theorem1}

Suppose that $F$ satisfies Assumptions 1-4,
	Let $\{x_k\}$ be the iterates generated by the idealized Algorithm~\ref{alg:adasgd} where $|S_{k}|$ is chosen such that the (exact) acute-angle test~\eqref{eq:exactest} and Hessian sub-sampling test ~\eqref{dhdtest} are satisfied at each iteration for any given constants $0 <\nu, \varepsilon, p < 1$. Then, for all $k$, starting from any $x_0$, 
	\begin{align*}\label{c-sample-norm}
	    \frac{(\nabla F_{S_k}(x_k)^{T} \nabla F(x_k))^2}{ \left\lVert\nabla F_{S_k}(x_k)\right\rVert^2}  \geq (1-\nu^2) \left\lVert\nabla F(x_k)\right\rVert^2.
	\end{align*}
	with probability at least $1-p$. Moreover, with probability $(1-p)^2$, we have
	\begin{equation*}
        F(x_{k+1}) \leq F(x_{k}) - \frac{\alpha}{2} \|\nabla F(x_k)\|^2,
    \end{equation*}  
	where $\alpha = \frac{(1-\nu^2)(1-\varepsilon)}{M (1+\frac{\gamma}{\sqrt{m}})} > 0.$
	\label{mainlemma}

Suppose that $F$ satisfies Assumptions 1-4,
	Let $\{x_k\}$ be the iterates generated by the idealized Algorithm~\ref{alg:adasgd} where $|S_{k}|$ is chosen such that the (exact) acute-angle test~\eqref{eq:exactest} and Hessian sub-sampling test ~\eqref{dhdtest} are satisfied at each iteration for any given constants $0 <\nu, \varepsilon, p < 1$. Then, for all $k$, starting from any $x_0$, with probability of at least $(1-p)^{2k}$, we have
	\begin{equation*} 
	    F(x_k) - F(x^*) \leq \rho^k (F(x_0) - F(x^*)),
	\end{equation*}
     where $\rho= 1 -m \alpha =  1 - \frac{m(1-\nu^2)(1-\varepsilon)}{M (1+\frac{\gamma}{\sqrt{m}})}.$
	\label{theorem2}

Let $0 <\nu\gamma, \varepsilon, p, \delta < 1$. Suppose that $F$ satisfies the Assumptions 1-4 and that we have an efficient way to compute $G(x)$ where \(\left\|\nabla F_{i}(\mathrm{x})\right\| \leq G(\mathrm{x}), \quad \forall i=1, \ldots, n\). Let $\{x_k, X_k, S_k\}$ be the set of iterates, and sample Hessian and gradient batches generated by taking the step $t_{k, \varepsilon}$ at iteration $k$ starting from any $x_0$, where $|S_{k}|, |X_{k}|$ are chosen such that Lemma \ref{gkprob} and Lemma \ref{dhdprob} are satisfied at each iteration. Then, for any $k$, with probability $(1-p)(1-\delta)$ we have :
	\begin{equation*} 
	    (F(x_{k+1}) - F(x^*)) \leq \rho (F(x_k) - F(x^*)),
	\end{equation*}
     where 
	\begin{equation*} 
	    \rho=  1 - \frac{m(1-\nu)^2(1-\varepsilon)}{2(1+\nu^2) M (1+\frac{\gamma}{\sqrt{m}})}.
	\end{equation*}

By Assumption 3, choosing $\nu \leq \frac{1}{\gamma}$ insures that the conditions for Lemma \ref{gkprob} are satisfied. Therefore, we have with probability $1-\delta$:

\begin{align*} 
\text{Lemma } \ref{gkprob}  &\implies \left\|g_{k}\right\|^{2}-g_{k}^{T} g=g_{k}^{T}\left(g_{k}-g\right) \leq\left\|g_{k}\right\|\left\|g-g_{k}\right\| \leq \nu\left\|g_{k}\right\|^{2}\\
&\implies g_{k}^{T} g \geq(1-\nu)\left\|g_{k}\right\|^{2}.
\end{align*}
Also:
\begin{align*} 
\eqref{gkprob} \implies \|g\|^{2}=\left\|g-g_{k}+g_{k}\right\|^{2} \leq 2\left\|g-g_{k}\right\|^{2}+2\left\|g_{k}\right\|^{2} \leq 2\left(1+\nu^{2}\right)\left\|g_{k}\right\|^{2}.
\end{align*}
Hence, with probability $1-\delta$:
\begin{align} 
\frac{\left(g_{k}^{T} g\right)^{2}}{\left\|g_{k}\right\|^{2}} \geq(1-\nu)^{2}\left\|g_{k}\right\|^{2} \geq \frac{(1-\nu)^{2}}{2\left(1+\nu^{2}\right)}\|g\|^{2} \label{lemma1part1}.
\end{align}
Let $\Delta (\delta_k, t) = (\delta_k + \rho_k)t + log(1-\delta_k t)$, using Lemma \eqref{selfconc}, we have:
\begin{equation}
\quad F(x_k+t d_k) \leq F(x_k)-\Delta (\delta_k, t).
\end{equation}
If we sample the Hessian at the rate described in Lemma \ref{dhdprob}, the following inequality is satisfied with probability $(1-p)$:
$$
 \inf_{d} \frac{|d^T(\nabla^{2} F_S(x)-\nabla^{2} F(\mathbf{x})) d|}{\|d\|^2} = \left\| \nabla^{2} F_S(x)-\nabla^{2} F(\mathbf{x})\right\| \leq \varepsilon m \leq \varepsilon \inf_{d} \frac{d^T \nabla^{2} F(\mathbf{x}) d}{\|d\|^2}.
$$
Taking $d = g_k$ results into the following inequalities being satisfied with  probability $(1-p)$:
\begin{equation}
    \frac{\hat{\delta_k}}{\sqrt{1+\varepsilon}} \leq \delta_k \leq \frac{\hat{\delta_k}}{\sqrt{1-\varepsilon}} = \hat{\delta}_{k, \varepsilon}.
\end{equation}
We have, for $t<\frac{1}{\delta}$:
$$
\frac{\partial \Delta}{\partial \delta}(\delta, t) = t-\frac{t}{1-\delta t} = \frac{\delta t^2}{1-\delta t} < 0.
$$
Using the monotonicity of $\Delta (., t)$, (14) and the choice of step size as $t_{k, \varepsilon} = \frac{\rho_{k}}{\left(\rho_{k}+\hat{\delta}_{k, \varepsilon}\right) \hat{\delta}_{k, \varepsilon}}$, we have:
\begin{equation}
\quad F(x_k+t_{k, \varepsilon} d_k) \leq F(x_k)-\Delta(\hat{\delta}_{k, \varepsilon}, t_{k, \varepsilon}).
\end{equation}
The choice of $t_{k, \varepsilon}$ is possible because we now prove that $t_{k, \varepsilon} < \frac{1}{\delta_k}$. Let $t(\delta) = \frac{\rho_k}{\delta (\delta+\rho_k)}$ clearly $t(.)$ is decreasing as a function of $\delta$. Using the inequality (14) we have
$$
t_{k, \varepsilon} = t(\hat{\delta}_{k, \varepsilon}) \leq t(\delta_k) = \frac{1}{\delta_k}-\frac{1}{\delta_k + \rho_k} \leq \frac{1}{\delta_k}.
$$


Now we obtain a decrease guarantee of the function with probability $(1-p)$
\begin{equation*}:
\quad F(x_k+t_{k, \varepsilon} d_k) \leq F(x_k)-\Delta(\hat{\delta}_{k, \varepsilon}, t_{k, \varepsilon}) = F(x_k)- \omega (\eta_{k, \varepsilon} ).
\end{equation*}

Now, using the Cauchy-Schwarz inequality, inequalities (14) and Assumption 1-3 we have:
\begin{equation*}
|\eta_{k, \varepsilon}| = |\frac{\rho_k}{\frac{\hat{\delta}_{k}}{\sqrt{1-\varepsilon}}}| \leq \frac{\|g\| \|g_k\|}{\delta_k} \leq \frac{\|g\| \|g_k\|}{\sqrt{g_k^T \nabla^2 F(x_k) g_k}} \leq \frac{\|g\|}{\sqrt{m}} \leq \frac{\gamma}{\sqrt{m}}.
\end{equation*}
By observing that $\omega(z) = z - log(1+z)$ satisfies $\omega(z) \geq \frac{1}{2}(1+\Gamma)^{-1} z^{2}$ for all $z \in[0, \Gamma]$, with probability $(1-p)$, we have:
 \begin{equation*}
     F(x_k+t_{k, \varepsilon}d_k)  \leq F(x_k) -  \frac{1-\varepsilon}{2(1+\frac{\gamma}{\sqrt{m}})} \hat{\eta}_{k}^2,
\end{equation*} 
with $\hat{\eta}_{k}=\frac{g_{k}^{T} g}{\hat{\delta}_{k}}$. Using Assumption 2, we have $\hat{\delta}_{k}^2 \leq M \|g_k\| ^2$. Therefore, we have:
 \begin{equation*}
     F(x_k+t_{k, \varepsilon} d_k)  \leq F(x_k) -  \frac{1-\varepsilon}{2 M (1+\frac{\gamma}{\sqrt{m}})} \frac{(g^T g_k)^2}{\|g_k\|^2}.
\end{equation*} 
Using \eqref{lemma1part1}, we have with probability $(1-p)(1-\delta)$:
 \begin{equation}
     F(x_k+t_{k, \varepsilon} d_k)  \leq F(x_k) -  \frac{(1-\nu)^2(1-\varepsilon)}{4(1+\nu^2) M (1+\frac{\gamma}{\sqrt{m}})} \|\nabla F(x_k)\|^2 \label{decreaselemma}.
\end{equation}
It is well known \citep{bertsekas2003convex} that for strongly convex functions:   
\[
\|\nabla F(x_k)\|^2 \geq 2m [F(x_k) - F(x^*)].
\]
 Substituting this in \eqref{decreaselemma} and subtracting $F(x^*)$ from both sides, we obtain with probability $(1-p)(1-\delta)$:
\begin{align*}
F(x_{k+1}) - F(x^*) &\leq  \rho (F(x_k) - F(x^*)), \nonumber
\end{align*}
with :
$$
\rho=  1 - \frac{m(1-\nu)^2(1-\varepsilon)}{2(1+\nu^2) M (1+\frac{\gamma}{\sqrt{m}})},
$$
which is the desired result.

